import React, { useState } from 'react';

function AddTrip({ setTrip }) {
    const [tripName, setTripName] = useState('');
    const [numMembers, setNumMembers] = useState(0);
    const [familyMembers, setFamilyMembers] = useState([]);

    const handleNumMembersChange = (e) => {
        const count = parseInt(e.target.value) || 0;
        setNumMembers(count);
        setFamilyMembers(Array(count).fill(''));
    };

    const handleMemberNameChange = (index, value) => {
        const updated = [...familyMembers];
        updated[index] = value;
        setFamilyMembers(updated);
    };

    const handleAddTrip = (e) => {
        e.preventDefault();
        setTrip({
            tripName,
            familyMembers
        });
    };

    return (
        <form onSubmit={handleAddTrip}>
            <h2>Add New Trip</h2>
            <label>Trip Name:</label><br />
            <input type="text" value={tripName} onChange={(e) => setTripName(e.target.value)} required /><br /><br />

            <label>Number of Familys :</label><br />
            <input type="number" value={numMembers} onChange={handleNumMembersChange} min="1" required /><br /><br />

            {familyMembers.map((name, index) => (
                <div key={index}>
                    <label>Member {index + 1}:</label><br />
                    <input
                        type="text"
                        value={name}
                        onChange={(e) => handleMemberNameChange(index, e.target.value)}
                        required
                    /><br /><br />
                </div>
            ))}

            <button type="submit">Create Trip</button>
        </form>
    );
}

export default AddTrip;
